#pragma once
#ifdef NANO_SYNC_FAULT
static CapellaStoreSnapshotLimits exit_fault_limits(const Json& bundle){auto limits=crash_limits;limits.blocks=bundle.at("blocks").get<size_t>();return limits;}
static Genesis exit_fault_genesis(const Json& bundle){Genesis g;g.chain_id=quantity(bundle.at("chainId"));g.consensus="beacon";g.evm_revision=EvmRevision::Shanghai;g.block=Block::from_json(bundle.at("genesis"));g.state=State::from_json(bundle.at("alloc"));return g;}
static Json exit_fault_observation(Blockchain& owner,CapellaDurableReactor& reactor,const CapellaForkBlockRules& rules,const CapellaStoreSnapshotLimits& limits){
 const auto current=reactor.current();const auto head_pin=capella_fork_head(*current.state,rules);const auto& head=*head_pin;const auto final_pin=current.state->blocks.at(current.state->timed.view.finalized.root).lease();const auto& final=*final_pin;const auto& t=rules.transition;
 check(owner.tip().header.hash()==head.execution_block.header.hash()&&owner.state().root()==head.execution_state.root()&&owner.finalized_block()->header.hash()==final.execution_block.header.hash(),"exit fault owner/consensus mismatch");
 const std::string recipient="0x000000000000000000000000000000000000002a";Int paid=0,final_paid=0;size_t capital=0,final_capital=0;
 for(Int height=0;height<=head.execution_block.header.number;++height){const auto block=owner.store().block_by_number(height);check(bool(block),"exit fault canonical history missing");for(const auto& w:block->withdrawals)if(quantity(w.at("validatorIndex"))==0){check(w.at("address")==recipient,"exit fault wrong withdrawal recipient");const auto amount=quantity(w.at("amount"));paid+=amount*1000000000;if(amount>Int("30000000000"))++capital;if(height<=final.execution_block.header.number){final_paid+=amount*1000000000;if(amount>Int("30000000000"))++final_capital;}}}
 check(capital<=1&&final_capital<=1&&head.execution_state.get(recipient).balance==paid&&final.execution_state.get(recipient).balance==final_paid,"exit fault duplicated or mixed withdrawal payment");
 const auto checkpoint=owner.store().fork_checkpoint(t.chain_id,owner.genesis().block.header.hash(),limits.envelope_bytes,current.token);check(bool(checkpoint),"exit fault checkpoint missing");
 const auto context=capella_fork_block_context(head.state,head.header,{t.consensus.epoch,t.execution,t.maximum_state_bytes},t.consensus.state);
 return {{"snapshot",checkpoint->snapshot},{"sequence",current.token.sequence},{"head",hex(head.execution_block.header.hash())},{"stateRoot",hex(head.execution_state.root())},{"finalized",hex(final.execution_block.header.hash())},{"paid",quantity(paid)},{"finalPaid",quantity(final_paid)},{"capital",capital},{"finalCapital",final_capital},{"exitEpoch",context.registry.validators.at(0).exit_epoch},{"archiveSize",Json::parse(checkpoint->snapshot).value("signedExits",Json::array()).size()}};
}
static int exit_lifecycle_writer(const fs::path& directory){
 const auto bundle=load(directory/"bundle.json");const auto profile=bundle.at("profile").get<std::string>();const auto rules=load_capella_fork_profile(profile,sha256(Bytes(profile.begin(),profile.end())),1024*1024);const auto limits=exit_fault_limits(bundle);const auto g=exit_fault_genesis(bundle);
 ChainStore witness(directory/"witness");Blockchain owner(directory/"db",g);CapellaDurableReactor node(owner,rules,limits,witness);const auto wire=unhex(bundle.at("wire").get<std::string>());
 auto apply=[&]{if(bundle.at("isTick").get<bool>()){node.tick(bundle.at("time").get<uint64_t>());return true;}return node.block(wire);};
 const bool fault_witness=bundle.at("faultWitness");fs::path wal;for(const auto& entry:fs::directory_iterator(directory/(fault_witness?"witness":"db")))if(entry.path().extension()==".log"&&(wal.empty()||entry.path().filename()>wal.filename()))wal=entry.path();check(!wal.empty(),"exit lifecycle WAL missing");const auto offset=fs::file_size(wal);
 Rpc rpc(owner);nano_test_arm_sync_fault(wal.c_str());bool failed=false;try{apply();}catch(const std::runtime_error&){failed=true;}check(failed&&nano_test_sync_failures()>0,"exit lifecycle fsync fault not reached");
 unsigned blocked=0;auto refuse=[&](auto action){try{action();}catch(const std::runtime_error&){++blocked;}};
 refuse([&]{node.current();});refuse([&]{apply();});refuse([&]{node.pending_exits();});refuse([&]{owner.store().latest();});refuse([&]{owner.store().fork_checkpoint(g.chain_id,g.block.header.hash(),limits.envelope_bytes);});refuse([&]{owner.tip();});refuse([&]{owner.state();});refuse([&]{owner.finalized_block();});check(blocked==(fault_witness?6:8),"exit lifecycle uncertainty remained accessible");
 check(rpc.handle(Json{{"jsonrpc","2.0"},{"id",1},{"method","eth_getBalance"},{"params",Json::array({"0x000000000000000000000000000000000000002a","latest"})}}).contains("error"),"uncertain exit payment served by RPC");
 std::cout<<Json{{"wal",wal.filename().string()},{"before",offset},{"after",fs::file_size(wal)},{"blocked",blocked}}.dump()<<std::endl;_exit(0);
}
// Caller closes both source databases before copying. No live RocksDB file copy.
static void qualify_exit_lifecycle_sync(const fs::path& source,const fs::path& source_witness,const CapellaForkBlockRules& rules,const CapellaStoreSnapshotLimits& limits,const Genesis& g,const Bytes& wire,const std::string& stage,bool is_tick,uint64_t time){
 auto apply=[&](CapellaDurableReactor& node){if(is_tick){node.tick(time);return true;}return node.block(wire);};
 auto copy=[&](const fs::path& directory){fs::copy(source,directory/"db",fs::copy_options::recursive);fs::copy(source_witness,directory/"witness",fs::copy_options::recursive);};
 Json old,next;{Temp reference;copy(reference.path);ChainStore witness(reference/"witness");Blockchain owner(reference/"db",g);CapellaDurableReactor node(owner,rules,limits,witness);old=exit_fault_observation(owner,node,rules,limits);check(apply(node),"exit fault reference operation rejected");next=exit_fault_observation(owner,node,rules,limits);check(next.at("sequence").get<uint64_t>()==old.at("sequence").get<uint64_t>()+1,"exit fault reference not one atomic publication");}
 if(stage=="inclusion")check(old.at("exitEpoch")==UINT64_MAX&&next.at("exitEpoch")!=UINT64_MAX&&next.at("archiveSize")==1,"inclusion fault not at requested boundary");
 if(stage=="archive-retirement")check(old.at("archiveSize")==1&&next.at("archiveSize")==0&&old.at("finalized")!=next.at("finalized"),"retirement fault not at finality boundary");
 if(stage=="payment")check(old.at("capital")==0&&next.at("capital")==1,"payment fault not at capital boundary");
 if(stage=="payment-finality")check(old.at("finalCapital")==0&&next.at("finalCapital")==1,"payment finality fault not at requested boundary");
 for(unsigned disposition=0;disposition<4;++disposition){const bool fault_witness=disposition>=2,lose=disposition%2;Temp temp;copy(temp.path);
  save(temp/"bundle.json",Json{{"profile",capella_fork_profile(rules).dump()},{"blocks",limits.blocks},{"chainId",quantity(g.chain_id)},{"genesis",g.block.to_json(true)},{"alloc",g.state.to_json()},{"wire",hex(wire)},{"faultWitness",fault_witness},{"isTick",is_tick},{"time",time}});
  const auto result=success(run({executable,"--exit-lifecycle-writer",temp.path.string()}));const auto wal=temp/(fault_witness?"witness":"db")/result.at("wal").get<std::string>();check(fs::file_size(wal)==result.at("after").get<uint64_t>()&&result.at("after")>result.at("before"),"exit fault WAL suffix absent");
  if(lose){const int fd=open(wal.c_str(),O_WRONLY);check(fd>=0,"open owned exit transition WAL");const bool ok=ftruncate(fd,result.at("before").get<uint64_t>())==0&&fsync(fd)==0;close(fd);check(ok,"truncate owned exit transition WAL");}
  ChainStore witness(temp/"witness");Blockchain owner(temp/"db",g);const auto primary=owner.store().fork_checkpoint(g.chain_id,g.block.header.hash(),limits.envelope_bytes);const bool primary_new=!fault_witness&&!lose;check(primary&&primary->snapshot==(primary_new?next:old).at("snapshot").get<std::string>(),"exit transition primary mixed old/new state");
  auto node=std::make_unique<CapellaDurableReactor>(owner,rules,limits,witness);const bool recovered_new=!(fault_witness&&lose);check(exit_fault_observation(owner,*node,rules,limits)==(recovered_new?next:old),"exit transition witness recovery differs from complete expected state");
  check(apply(*node)&&exit_fault_observation(owner,*node,rules,limits)==next,"exit transition retry differs");const auto token=node->current().token;check(apply(*node)&&node->current().token==token,"exit transition duplicate republished");
  node.reset();node=std::make_unique<CapellaDurableReactor>(owner,rules,limits,witness);check(exit_fault_observation(owner,*node,rules,limits)==next,"exit transition changed after second reopen");
  std::cout<<Json{{"scenario","capella-exit-lifecycle-sync"},{"stage",stage},{"operation",is_tick?"clock-tick":"block"},{"faultWitness",fault_witness},{"lostSuffix",lose},{"blockedOperations",result.at("blocked")},{"exactRecovery",true},{"retryIdempotent",true},{"capitalPayments",next.at("capital")},{"finalizedCapitalPayments",next.at("finalCapital")},{"archiveSize",next.at("archiveSize")},{"physicalPowerLoss",false}}.dump()<<std::endl;
 }
}
#endif
